new=r'''const compressPhoto = async (file: File): Promise<File> => { if (file.size <= 500 * 1024) return file; const image = await new Promise<HTMLImageElement>((resolve, reject) => { const img = new Image(); img.onload = () => resolve(img); img.onerror = reject; img.src = URL.createObjectURL(file); }); const scale = Math.min(1, Math.sqrt((500 * 1024) / file.size)); const canvas = document.createElement("canvas"); canvas.width = Math.max(640, Math.round(image.width * scale)); canvas.height = Math.max(480, Math.round(image.height * scale)); const ctx = canvas.getContext("2d"); if (!ctx) return file; ctx.drawImage(image, 0, 0, canvas.width, canvas.height); let quality = .82; let blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/jpeg", quality)); while (blob && blob.size > 500 * 1024 && quality > .35) { quality -= .1; blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/jpeg", quality)); } return blob ? new File([blob], file.name.replace(/\.[^.]+$/, ".jpg"), { type: "image/jpeg" }) : file; };
  const saveRetire = async () => { if (!modalTool || !retireReason.trim() || !incidentDate || !supervisorCode) return notify("Completa motivo, fecha y supervisor responsable."); try { const compressed = await Promise.all(retirementPhotos.slice(0, 5).map(compressPhoto)); const form = new FormData(); form.append("idTag", modalTool.code); form.append("motivo", retireReason.trim()); form.append("fechaIncidente", String(new Date(`${incidentDate}T12:00:00`).getTime())); form.append("supervisorCodigo", supervisorCode); compressed.forEach((photo) => form.append("photos", photo, photo.name)); const response = await fetch("/api/retirements/report", { method: "POST", body: form, credentials: "include" }); if (!response.ok) { const payload = await response.json().catch(() => ({})); throw new Error(payload.message || `Error ${response.status} al generar reporte.`); } const pdf = await response.blob(); const url = URL.createObjectURL(pdf); const link = document.createElement("a"); link.href = url; link.download = `Reporte_FS_${modalTool.code}_${incidentDate.replace(/-/g, "")}.pdf`; link.click(); URL.revokeObjectURL(url); await utils.catalog.snapshot.invalidate(); setModalTool(null); setRetireReason(""); setIncidentDate(""); setSupervisorCode(""); setRetirementPhotos([]); notify("Baja registrada y reporte PDF descargado"); } catch (error) { notify(error instanceof Error ? error.message : "No se pudo generar el reporte."); } };
  '''
