modal=r'''<p><b>{modalTool.code} · {modalTool.name}</b> pasará a Fuera de Servicio. Se generará un reporte PDF de auditoría.</p><label>Herramienta<input value={modalTool.code} readOnly /></label><label>Descripción<input value={modalTool.name} readOnly /></label><label>Almacenero responsable<input value={me.data!.name ?? ""} readOnly /></label><label>Supervisor responsable<select required value={supervisorCode} onChange={(e)=>setSupervisorCode(e.target.value)}><option value="">Seleccionar supervisor</option>{people.map((person)=><option key={person.code} value={person.code}>{person.code} · {person.fullName}</option>)}</select></label><label>Fecha del incidente<input type="date" required value={incidentDate} onChange={(e)=>setIncidentDate(e.target.value)} /></label><label>Motivo obligatorio<textarea autoFocus required minLength={3} placeholder="Describe por qué está fuera de servicio…" value={retireReason} onChange={(e)=>setRetireReason(e.target.value)} /></label><label>Evidencias fotográficas (máximo 5)<input type="file" accept="image/*" multiple onChange={(e)=>setRetirementPhotos(Array.from(e.target.files ?? []).slice(0,5))} /><small>{retirementPhotos.length ? `${retirementPhotos.length} foto(s) seleccionada(s); se comprimirán a máximo 500 KB cada una.` : "Opcional: adjunta hasta 5 fotos."}</small></label>'''
