typeahead=r'''function Typeahead({ label, placeholder, value, setValue, selected, onClear, suggestions, disabled = false }: { label: string; placeholder: string; value: string; setValue: (value: string) => void; selected: string; onClear: () => void; suggestions: Array<{ key: string; label: string; sub: string; onPick: () => void }>; disabled?: boolean }) { return <label className={`typeahead ${disabled ? "typeahead-disabled" : ""}`}><span>{label}</span><div className="search-box"><Search size={17} /><input disabled={disabled} value={value} placeholder={placeholder} onChange={(e) => { setValue(e.target.value); }} /><button type="button" disabled={disabled} onClick={onClear}><X size={15} /></button></div>{value && !selected && !disabled && <div className="suggestions">{suggestions.length ? suggestions.map((item) => <button type="button" key={item.key} onClick={item.onPick}><b>{item.label}</b><small>{item.sub}</small></button>) : <span>No hay coincidencias</span>}</div>}{selected && <em className="selected-chip"><Check size={14} />{selected}</em>}</label>; }
'''
